from collections import defaultdict
from heapq import heappush, heappop

def solve(edges: list[list], start: str, end: str):
    if start == end:
        return [0, [start]]

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = {start: (0, 0, [start])}
    heap = [(0, 0, start, [start])]

    while heap:
        total_weight, edge_count, node, path = heappop(heap)

        if (node, tuple(path)) in dist and dist[(node, tuple(path))] <= (total_weight, edge_count):
            continue

        if node == end:
            return [total_weight, path]

        for neighbor, weight in graph.get(node, []):
            new_weight = total_weight + weight
            new_edge_count = edge_count + 1
            new_path = path + [neighbor]
            new_state = (new_weight, new_edge_count, neighbor, new_path)

            if (neighbor, tuple(new_path)) not in dist or \
               dist[(neighbor, tuple(new_path))] > (new_weight, new_edge_count):
                dist[(neighbor, tuple(new_path))] = (new_weight, new_edge_count)
                heappush(heap, new_state)

    return None

