def solve(dimensions: list[int]) -> list:
    n = len(dimensions) - 1
    if n == 0:
        return [0, ""]
    if n == 1:
        return [0, "A1"]

    dp = [[0] * n for _ in range(n)]
    parenthes = [[""] * n for _ in range(n)]

    for i in range(n):
        parenthes[i][i] = f"A{i+1}"

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')

            for k in range(i, j):
                cost = dp[i][k] + dp[k+1][j] + dimensions[i] * dimensions[k+1] * dimensions[j+1]
                rendering = f"({parenthes[i][k]}{parenthes[k+1][j]})"

                if cost < dp[i][j] or (cost == dp[i][j] and rendering < parenthes[i][j]):
                    dp[i][j] = cost
                    parenthes[i][j] = rendering

    return [dp[0][n-1], parenthes[0][n-1]]

def solve(dimensions: list[int]) -> list:
    n = len(dimensions) - 1
    if n == 0:
        return [0, ""]

    if n == 1:
        return [0, "A1"]

    # dp[i][j] = (min_cost, best_rendering) for multiplying matrices i..j (1-indexed)
    dp = {}

    # Initialize for single matrices
    for i in range(1, n + 1):
        dp[(i, i)] = (0, f"A{i}")

    # Fill dp table for increasing chain lengths
    for length in range(2, n + 1):
        for i in range(1, n - length + 2):
            j = i + length - 1
            best_cost = float('inf')
            best_rendering = None

            for k in range(i, j):
                left_cost, left_render = dp[(i, k)]
                right_cost, right_render = dp[(k + 1, j)]

                cost = left_cost + right_cost + dimensions[i - 1] * dimensions[k] * dimensions[j]
                rendering = f"({left_render}{right_render})"

                if cost < best_cost or (cost == best_cost and rendering < best_rendering):
                    best_cost = cost
                    best_rendering = rendering

            dp[(i, j)] = (best_cost, best_rendering)

    return [dp[(1, n)][0], dp[(1, n)][1]]

