def solve(length: int, fragments: list[list]) -> str | None:
    result = [None] * length

    for offset, text in fragments:
        for i, char in enumerate(text):
            pos = offset + i
            if pos >= length:
                continue
            if result[pos] is not None and result[pos] != char:
                return None
            result[pos] = char

    if any(x is None for x in result):
        return None

    return ''.join(result)

