def solve(jobs: list[list[int]]) -> list[list[int]]:
    n = len(jobs)
    completed = [False] * n
    job_info = []
    for i, (release, duration, priority) in enumerate(jobs):
        job_info.append({
            'index': i, 'release': release, 'duration': duration, 'priority': priority
        })

    result = []
    current_time = 0

    while len(result) < n:
        available = []
        for job in job_info:
            if not completed[job['index']] and job['release'] <= current_time:
                available.append(job)

        if available:
            available.sort(key=lambda x: (x['priority'], x['release'], x['index']))
            job = available[0]
            job['completion_time'] = current_time + job['duration']
            result.append([job['index'], job['completion_time']])
            completed[job['index']] = True
            current_time = job['completion_time']
        else:
            current_time = min(job['release'] for job in job_info if not completed[job['index']])

    return result

