def solve(value: int) -> str:
    if value == 0:
        return "0"

    digits = []
    while value != 0:
        remainder = value % 3
        if remainder == 0:
            digits.append("0")
            value //= 3
        elif remainder == 1:
            digits.append("1")
            value //= 3
        elif remainder == 2:
            digits.append("T")
            value = value // 3 + 1
        elif remainder == -1:
            digits.append("T")
            value = value // 3 - 1
        elif remainder == -2:
            digits.append("1")
            value = value // 3 - 1

    result = ''.join(reversed(digits))
    return result

def solve(value: int) -> str:
    if value == 0:
        return "0"

    result = []
    abs_value = abs(value)

    while abs_value > 0:
        remainder = abs_value % 3

        if remainder == 0:
            result.append('0')
            abs_value //= 3
        elif remainder == 1:
            result.append('1')
            abs_value //= 3
        else:  # remainder == 2
            result.append('T')
            abs_value = abs_value // 3 + 1

    # Handle negative numbers
    if value < 0:
        inverted = []
        for digit in result:
            if digit == '0':
                inverted.append('0')
            elif digit == '1':
                inverted.append('T')
            else:  # 'T'
                inverted.append('1')

        # Add 1 to handle the sign
        carry = 1
        for i in range(len(inverted) - 1, -1, -1):
            if carry == 0:
                break

            digit = inverted[i]
            if digit == '0':
                inverted[i] = '1'
                carry = 0
            elif digit == '1':
                inverted[i] = '0'
                carry = 1
            else:  # 'T'
                inverted[i] = 'T'
                carry = 0

        if carry:
            inverted.insert(0, '1')

        result = inverted

    return ''.join(reversed(result))

def solve(value: int) -> str:
    if value == 0:
        return "0"

    result = []
    is_negative = value < 0

    if is_negative:
        value = abs(value)

    quotient = value
    while quotient != 0:
        remainder = quotient % 3

        if remainder == 2:
            result.append('T')
            quotient = quotient // 3 + 1
        else:
            result.append(str(remainder) if remainder != 1 else '1')
            quotient = quotient // 3

    if is_negative and result[-1] != '0':
        balanced = ''.join(reversed(result))
        if balanced[0] == '0':
            return '0'
        return balanced

    return ''.join(reversed(result))

