def solve(nodes: list[str], edges: list[list[str]]) -> list[list[str]] | None:
    # Create working copies to avoid mutating inputs
    graph = {node: set() for node in nodes}
    indegree = {node: 0 for node in nodes}

    # Build graph with duplicate edges handled
    for source, dest in edges:
        graph[source].add(dest)
        indegree[dest] += 1

    processed = set()
    result = []

    while len(processed) < len(nodes):
        # Find all zero-indegree nodes not yet processed
        zero_indegree = [node for node in nodes if indegree[node] == 0 and node not in processed]

        if not zero_indegree:
            # Nodes remain but no zero-indegree available (cycle)
            return None

        # Sort lexicographically and add as a layer
        zero_indegree.sort()
        result.append(zero_indegree)

        # Process this layer: remove outgoing edges
        for node in zero_indegree:
            processed.add(node)
            for neighbor in graph[node]:
                indegree[neighbor] -= 1

    return result

def solve(nodes: list[str], edges: list[list[str]]) -> list[list[str]] | None:
    remaining_nodes = list(nodes)
    adj_list = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    edge_set = set()
    for source, dest in edges:
        if (source, dest) not in edge_set:
            edge_set.add((source, dest))
            adj_list[source].append(dest)
            indegree[dest] += 1

    result = []

    while remaining_nodes:
        zero_indegree = [node for node in remaining_nodes if indegree[node] == 0]

        if not zero_indegree:
            return None

        zero_indegree.sort()
        result.append(zero_indegree)

        remaining_nodes = [node for node in remaining_nodes if node not in zero_indegree]

        for node in zero_indegree:
            for neighbor in adj_list[node]:
                indegree[neighbor] -= 1

    return result

def solve(nodes: list[str], edges: list[list[str]]) -> list[list[str]] | None:
    from copy import deepcopy

    if not nodes:
        return []

    # Calculate indegree for each node
    indegree = {node: 0 for node in nodes}
    edge_copy = deepcopy(edges)

    for source, dest in edge_copy:
        indegree[dest] = indegree.get(dest, 0) + 1

    result = []
    nodes_remaining = set(nodes)

    while nodes_remaining:
        # Find zero-indegree nodes
        zero_nodes = [node for node in nodes_remaining if indegree.get(node, 0) == 0]

        if not zero_nodes:
            return None

        # Sort lexicographically
        zero_nodes.sort()
        result.append(zero_nodes)

        # Remove these nodes and their outgoing edges
        for node in zero_nodes:
            nodes_remaining.remove(node)

            # Remove all edges originating from this node
            edge_copy = [[s, d] for s, d in edge_copy if s != node]

            # Update indegrees of nodes that had edges from this node
            for source, dest in edge_copy:
                if source == node:
