def solve(pattern: str, text: str) -> bool:
    if pattern == "":
        return text == ""

    # Preprocess pattern: handle escaping and collapse adjacent stars
    tokens = []
    i = 0
    n = len(pattern)

    while i < n:
        if pattern[i] == "\\":
            tokens.append(pattern[i + 1])
            i += 2
        elif pattern[i] == "*" and (not tokens or tokens[-1] != "*"):
            tokens.append("*")
            i += 1
        else:
            tokens.append(pattern[i])
            i += 1

    # DP table: dp[i][j] = can we match tokens[0:i] with text[0:j]
    m, n = len(tokens), len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(1, m + 1):
        if tokens[i - 1] == "*":
            dp[i][0] = dp[i - 1][0]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            token = tokens[i - 1]

            if token == "*":
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif token == "?" or token == text[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]

