    if not (1 <= result_date.year <= 9999):
        return None

    result_jan4 = date(result_date.year, 1, 4)
    result_jan4_weekday = result_jan4.weekday()
    result_monday_week1 = result_jan4 - timedelta(days=result_jan4_weekday)

    if monday_week1 != result_monday_week1:
        return None

    return result_date.strftime("%Y-%m-%d")

