    week1_monday = jan_4 - timedelta(days=jan_4.weekday())

    # Calculate target date
    target = week1_monday + timedelta(weeks=week-1, days=weekday-1)

    # Validate resulting year
    if not (1 <= target.year <= 9999):
        return None

    return target.strftime("%Y-%m-%d")

