def solve(operations):
    stack = []
    pop_results = []
    transaction_stack = [(stack.copy(), pop_results.copy())]  # Initial state

    for op in operations:
        if op[0] == "push":
            stack.append(op[1])
        elif op[0] == "pop":
            val = stack.pop()
            pop_results.append(val)
        elif op[0] == "dup":
            stack.append(stack[-1])
        elif op[0] == "swap":
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op[0] == "add":
            b, a = stack.pop(), stack.pop()
            stack.append(b + a)
        elif op[0] == "sub":
            b, a = stack.pop(), stack.pop()
            stack.append(b - a)
        elif op[0] == "begin":
            transaction_stack.append((stack.copy(), pop_results.copy()))
        elif op[0] == "commit":
            transaction_stack.pop()  # Discard most recent save
        elif op[0] == "rollback":
            # Restore all the way to the matched begin state
            while len(transaction_stack) > 1:
                transaction_stack.pop()
            stack, pop_results = transaction_stack[0]

    return [stack, pop_results]

