def solve(total: int, weights: list[int]) -> list[int]:
    n = len(weights)
    if total == 0:
        return [0] * n

    total_abs = abs(total)
    weight_sum = sum(weights)

    # Handle zero weights - they get zero shares
    shares = [0] * n
    remaining_total = total_abs

    if weight_sum > 0:
        # Calculate floor shares using integer arithmetic
        for i in range(n):
            if weights[i] > 0:
                shares[i] = (total_abs * weights[i]) // weight_sum

        # Calculate remaining to distribute
        distributed = sum(shares)
        remaining = total_abs - distributed

        if remaining > 0:
            # Calculate fractional parts for tie-breaking
            fractional_parts = []
            for i in range(n):
                if weights[i] > 0:
                    exact_share = (total_abs * weights[i]) / weight_sum
                    fractional_parts.append((i, exact_share - int(shares[i])))

            # Sort by fractional part (descending), then by index (ascending for ties)
            fractional_parts.sort(key=lambda x: (-x[1], x[0]))

            # Distribute remaining to recipients with largest fractional parts
            for i in range(remaining):
                if i < len(fractional_parts):
                    idx = fractional_parts[i][0]
                    shares[idx] += 1

    # Handle negative total
    if total < 0:
        shares = [-s for s in shares]

    return shares

