def solve(blocks: list[str]) -> list[str]:
    def ip_to_int(ip: str) -> int:
        parts = ip.split('.')
        return (int(parts[0]) << 24) | (int(parts[1]) << 16) | (int(parts[2]) << 8) | int(parts[3])

    def int_to_ip(n: int) -> str:
        return f"{(n >> 24) & 255}.{(n >> 16) & 255}.{(n >> 8) & 255}.{n & 255}"

    def block_to_range(block: str) -> tuple[int, int]:
        ip_str, prefix_str = block.split('/')
        ip = ip_to_int(ip_str)
        prefix = int(prefix_str)
        mask = (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF if prefix > 0 else 0
        network = ip & mask
        broadcast = network | (~mask & 0xFFFFFFFF)
        return (network, broadcast)

    def range_to_blocks(start: int, end: int) -> list[str]:
        result = []
        while start <= end:
            # Find the largest power of 2 aligned block that fits
            size = 1
            while True:
                next_size = size << 1
                if (next_size <= (end - start + 1) and
                    (start & (next_size - 1)) == 0):
                    size = next_size
                else:
                    break

            prefix = 32 - (size.bit_length() - 1)
            result.append(f"{int_to_ip(start)}/{prefix}")
            start += size
        return result

    # Convert input to ranges and merge
    ranges = [block_to_range(block) for block in blocks]
    ranges.sort()

    merged = []
    for start, end in ranges:
        if not merged or start > merged[-1][1] + 1:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)

    # Convert merged ranges to CIDR blocks
    result = []
    for start, end in merged:
        result.extend(range_to_blocks(start, end))

    return result

