def solve(items: list[str]) -> list[str]:
    def split_into_runs(s: str) -> list[tuple[str, bool]]:
        runs = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                runs.append((s[i:j], True))
                i = j
            else:
                j = i
                while j < n and not s[j].isdigit():
                    j += 1
                runs.append((s[i:j], False))
                i = j
        return runs

    def compare_strings(a: str, b: str) -> int:
        runs_a = split_into_runs(a)
        runs_b = split_into_runs(b)

        min_len = min(len(runs_a), len(runs_b))
        for i in range(min_len):
            a_run, a_is_digit = runs_a[i]
            b_run, b_is_digit = runs_b[i]

            if a_is_digit and b_is_digit:
                a_val = int(a_run)
                b_val = int(b_run)
                if a_val != b_val:
                    return -1 if a_val < b_val else 1
            elif not a_is_digit and not b_is_digit:
                a_lower = a_run.lower()
                b_lower = b_run.lower()
                if a_lower != b_lower:
                    return -1 if a_lower < b_lower else 1
            else:
                return -1 if a_is_digit else 1

        if len(runs_a) < len(runs_b):
            return -1
        elif len(runs_a) > len(runs_b):
            return 1

        digit_runs_a = [r for r, is_digit in runs_a if is_digit]
        digit_runs_b = [r for r, is_digit in runs_b if is_digit]

        for i in range(min(len(digit_runs_a), len(digit_runs_b))):
            a_run = digit_runs_a[i]
            b_run = digit_runs_b[i]

            a_leading_zeros = len(a_run) - len(str(int(a_run)))
            b_leading_zeros = len(b_run) - len(str(int(b_run)))

            if a_leading_zeros != b_leading_zeros:
                return -1 if a_leading_zeros < b_leading_zeros else 1

        return -1 if a < b else (1 if a > b else 0)

    return sorted(items, key=lambda x: (tuple(split_into_runs(x)), [r for r, is_digit in split_into_runs(x) if is_digit], x))

