def solve(items: List[str]) -> List[str]:
    def split_into_runs(s: str) -> List[Tuple[str, str]]:
        runs = []
        current_run = []
        current_type = None  # 'digit' or 'text'

        for char in s:
            if char.isdigit():
                if current_type != 'digit':
                    if current_run:
                        runs.append((''.join(current_run), current_type))
                    current_run = [char]
                    current_type = 'digit'
                else:
                    current_run.append(char)
            else:
                if current_type != 'text':
                    if current_run:
                        runs.append((''.join(current_run), current_type))
                    current_run = [char]
                    current_type = 'text'
                else:
                    current_run.append(char)

        if current_run:
            runs.append((''.join(current_run), current_type))

        return runs

    def compare_runs(run1: Tuple[str, str], run2: Tuple[str, str]) -> int:
        value1, type1 = run1
        value2, type2 = run2

        if type1 == type2 == 'digit':
            num1, num2 = int(value1), int(value2)
            if num1 != num2:
                return num1 - num2
        elif type1 == type2 == 'text':
            if value1.lower() != value2.lower():
                return -1 if value1.lower() < value2.lower() else 1
        else:
            if type1 == 'digit' and type2 == 'text':
                return -1
            elif type1 == 'text' and type2 == 'digit':
                return 1

        return 0

    def compare_sequences(seq1: List[Tuple[str, str]], seq2: List[Tuple[str, str]]) -> int:
        i = 0
        while i < len(seq1) and i < len(seq2):
            cmp = compare_runs(seq1[i], seq2[i])
            if cmp != 0:
                return cmp

            if i == len(seq1) - 1 and i < len(seq2) - 1:
                return -1
            elif i == len(seq2) - 1 and i < len(seq1) - 1:
                return 1

            i += 1

        if len(seq1) < len(seq2):
            return -1
        elif len(seq1) > len(seq2):
            return 1

        return 0

    def get_digit_run_lengths(runs: List[Tuple[str, str]]) -> List[int]:
        lengths = []
        for value, type_ in runs:
            if type_ == 'digit':
                lengths.append(len(value))
        return lengths

    def compare_items(item1: str, item2: str) -> int:
        runs1 = split_into_runs(item1)
        runs2 = split_into_runs(item2)

        cmp = compare_sequences(runs1, runs2)
        if cmp != 0:
            return cmp

        lengths1 = get_digit_run_lengths(runs1)
        lengths2 = get_digit_run_lengths(runs2)

        if lengths1 != lengths2:
            for i in range(min(len(lengths1), len(lengths2))):
                if lengths1[i] != lengths2[i]:
                    return lengths1[i] - lengths2[i]
            return len(lengths1) - len(lengths2)

        return -1 if item1 < item2 else (1 if item1 > item2 else 0)

    result = items.copy()
    for i in range(len(result)):
        for j in range(i + 1, len(result)):
            if compare_items(result[i], result[j]) > 0:
                result[i], result[j] = result[j], result[i]

    return result

