    def split_runs(s: str) -> list[tuple[str, str]]:
        runs = []
        i = 0
        while i < len(s):
            j = i
            if s[i].isdigit():
                while j < len(s) and s[j].isdigit():
                    j += 1
                runs.append(('digit', s[i:j]))
            else:
                while j < len(s) and not s[j].isdigit():
                    j += 1
                runs.append(('text', s[i:j]))
            i = j
        return runs

    def compare_run(a: tuple[str, str], b: tuple[str, str]) -> int:
        type_a, val_a = a
        type_b, val_b = b

        if type_a == 'digit' and type_b == 'digit':
            num_a = int(val_a)
            num_b = int(val_b)
            return num_a - num_b
        elif type_a == 'text' and type_b == 'text':
            text_a = val_a.lower()
            text_b = val_b.lower()
            if text_a < text_b:
                return -1
            elif text_a > text_b:
                return 1
            else:
                return 0
        else:
            return -1 if type_a == 'digit' else 1

    def get_sort_key(s: str) -> tuple:
        runs = split_runs(s)
