        for type_, val in runs:
            if type_ == 'digit':
                run_keys.append(int(val))
                digit_lengths.append(len(val))
            else:
                run_keys.append(val.lower())

        return (run_keys, digit_lengths, s)

    return sorted(items, key=get_sort_key)

