def solve(items: list[str]) -> list[str]:
    def split_into_runs(s: str):
        runs = []
        i = 0
        while i < len(s):
            is_digit = s[i].isdigit()
            start = i
            while i < len(s) and (s[i].isdigit() == is_digit):
                i += 1
            runs.append(s[start:i])
        return runs

    def compare_items(a: str, b: str):
        runs_a = split_into_runs(a)
        runs_b = split_into_runs(b)

        # Rule 1: Compare run sequences element by element
        for i in range(min(len(runs_a), len(runs_b))):
            run_a = runs_a[i]
            run_b = runs_b[i]

            if run_a.isdigit() and run_b.isdigit():
                num_a = int(run_a)
                num_b = int(run_b)
                if num_a != num_b:
                    return num_a - num_b
            elif run_a.isdigit():
                return -1  # Digit run < Text run
            elif run_b.isdigit():
                return 1   # Text run > Digit run
            else:
                text_a = run_a.lower()
                text_b = run_b.lower()
                if text_a != text_b:
                    return -1 if text_a < text_b else 1

        # One sequence is prefix of the other
        if len(runs_a) != len(runs_b):
            return len(runs_a) - len(runs_b)

        # Rule 2: Compare digit run lengths lexicographically
        digit_lengths_a = [len(r) for r in runs_a if r.isdigit()]
        digit_lengths_b = [len(r) for r in runs_b if r.isdigit()]

        for i in range(min(len(digit_lengths_a), len(digit_lengths_b))):
            if digit_lengths_a[i] != digit_lengths_b[i]:
                return digit_lengths_a[i] - digit_lengths_b[i]

        if len(digit_lengths_a) != len(digit_lengths_b):
            return len(digit_lengths_a) - len(digit_lengths_b)

        # Rule 3: Compare original strings
        return -1 if a < b else (1 if a > b else 0)

    return sorted(items, key=functools.cmp_to_key(compare_items))

import re
from typing import List, Tuple, Union

def _split_to_runs(s: str) -> List[Tuple[str, str]]:
    """Split string into runs of consecutive digits or non-digits.
    Returns list of (type, value) where type is 'digit' or 'text'."""
    runs = []
    digit_match = re.compile(r'\d+')
    text_match = re.compile(r'[^\d]+')

    pos = 0
    while pos < len(s):
        digit_match_obj = digit_match.match(s, pos)
        text_match_obj = text_match.match(s, pos)

        if digit_match_obj and (not text_match_obj or digit_match_obj.end() > text_match_obj.start()):
            runs.append(('digit', digit_match_obj.group()))
            pos = digit_match_obj.end()
        elif text_match_obj:
            runs.append(('text', text_match_obj.group()))
            pos = text_match_obj.end()
        else:
            break

    return runs

def _compare_runs(runs1: List[Tuple[str, str]], runs2: List[Tuple[str, str]]) -> int:
    """Compare two run sequences according to rule 1."""
    for (type1, val1), (type2, val2) in zip(runs1, runs2):
        if type1 == 'digit' and type2 == 'digit':
            # Compare as integers, so "007" equals "7"
            int1, int2 = int(val1), int(val2)
            if int1 != int2:
                return int1 - int2
        elif type1 == 'text' and type2 == 'text':
            # Compare case-insensitive, using lowercase for comparison
            text1, text2 = val1.lower(), val2.lower()
            if text1 != text2:
                return -1 if text1 < text2 else 1
        else:
            # One is digit, one is text
            # Digit runs are smaller than text runs
            return -1 if type1 == 'digit' else 1

    # If all compared runs are equal, the shorter sequence is smaller
    return len(runs1) - len(runs2)

def _digit_run_lengths(runs: List[Tuple[str, str]]) -> List[int]:
    """Extract digit run lengths (number of digits) for comparison."""
    lengths = []
    for type_, val in runs:
        if type_ == 'digit':
            lengths.append(len(val))
    return lengths

def _solve_custom(items: List[str]) -> List[str]:
    """Main solve function implementing all three comparison rules."""
    # Split all strings into runs
    run_lists = [_split_to_runs(s) for s in items]

    # Custom comparison function
    def compare(i1: int, i2: int) -> int:
        # Rule 1: Compare run sequences
        cmp = _compare_runs(run_lists[i1], run_lists[i2])
        if cmp != 0:
            return cmp

        # Rule 2: Compare digit run lengths as a list
        # Get the digit run lengths for both strings
        len1 = _digit_run_lengths(run_lists[i1])
        len2 = _digit_run_lengths(run_lists[i2])

        # Compare lexicographically
        for d1, d2 in zip(len1, len2):
            if d1 != d2:
                return d1 - d2

        # If all compared lengths are equal, the shorter list is smaller
        if len(len1) != len(len2):
            return len(len1) - len(len2)

        # Rule 3: Compare original strings
        return -1 if items[i1] < items[i2] else (1 if items[i1] > items[i2] else 0)

    # Sort using custom comparison
    result = items.copy()
    n = len(result)

    # Simple insertion sort for stability
    for i in range(1, n):
        key_idx = i
        key_val = items[i]
        key_runs = run_lists[i]

        # Move elements of result[0..i-1] that are greater than key
        j = i - 1
        while j >= 0 and compare(j, key_idx) > 0:
            result[j + 1] = result[j]
            run_lists[j + 1] = run_lists[j]
            j -= 1

        result[j + 1] = key_val
        run_lists[j + 1] = key_runs

    return result

def solve(items: List[str]) -> List[str]:
    """Return a new list with strings in natural order."""
    return _solve_custom(items)

