    if frac_part_str:
        frac_mult = 1.0 / src
        for c in frac_part_str:
            frac_part_decimal += char_to_value(c) * frac_mult
            frac_mult /= src

    # Total value
    total = int_part_decimal + frac_part_decimal
    if sign == -1:
