    int_result = int(total)
    frac_result = total - int_result

    # Convert integer part to dst base
    if int_result == 0:
        int_str = '0'
    else:
        int_str = ''
        temp = int_result
        while temp > 0:
            int_str = value_to_char(temp % dst) + int_str
