    # Convert fractional part to dst base with exactly `places` digits
    frac_str = ''
    current = frac_result
    for _ in range(places):
        current *= dst
        digit = int(current)
        frac_str += value_to_char(digit)
        current -= digit

    # Combine
    if places > 0:
        return result_sign + int_str + '.' + frac_str
    else:
        return result_sign + int_str

