    def is_leap_year(year):
        return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0

    def days_in_month(year, month):
        if month in [1, 3, 5, 7, 8, 10, 12]:
            return 31
        elif month in [4, 6, 9, 11]:
            return 30
        elif month == 2:
            return 29 if is_leap_year(year) else 28

    def is_last_day_of_month(year, month, day):
        return day == days_in_month(year, month)

    year, month, day = map(int, date.split('-'))

    if months == 0:
        return date

    total_months = year * 12 + month - 1 + months
    new_year = total_months // 12
    new_month = (total_months % 12) + 1

    dest_month_days = days_in_month(new_year, new_month)

    if is_last_day_of_month(year, month, day):
        result_day = dest_month_days
    else:
        result_day = min(day, dest_month_days)

    return f"{new_year:04d}-{new_month:02d}-{result_day:02d}"

