from typing import List, Tuple

def solve(buildings: List[Tuple[int, int, int]]) -> List[Tuple[int, int]]:
    events = []
    for left, right, height in buildings:
        if height > 0:
            events.append((left, height, 1))  # start event
            events.append((right, height, -1)) # end event

    events.sort(key=lambda e: (e[0], -e[2]))

    max_heap = [0]  # negative of actual height for max-heap
    height_counts = {0: 1}
    active_heights = set([0])

    result = []
    prev_height = 0

    for x, h, typ in events:
        if typ == 1:
            if h not in height_counts:
                height_counts[h] = 0
            height_counts[h] += 1
            active_heights.add(h)
        else:
            height_counts[h] -= 1
            if height_counts[h] == 0:
                active_heights.remove(h)

        # Update max_heap to reflect current active heights
        if h in active_heights:
            if -h not in max_heap:
                heapq.heappush(max_heap, -h)
        else:
            # Mark for removal (lazy removal)
            pass

        # Clean up max_heap - remove inactive heights
        while max_heap and (-max_heap[0] not in active_heights):
            heapq.heappop(max_heap)

        current_height = -max_heap[0] if max_heap else 0

        if current_height != prev_height:
            result.append((x, current_height))
            prev_height = current_height

    return result

