        # Octal: 0o/0O followed by digits 0-7 with optional underscore rules
        body = text[2:]
        if body and all(c in '01234567' or c == '_' for c in body):
            if body.startswith('_') or body.endswith('_') or '__' in body:
                return None
            return int(text, 8)

    elif text.startswith(('0x', '0X')):
        # Hexadecimal: 0x/0X followed by digits 0-9/a-f/A-F with optional underscore rules
        body = text[2:]
        if body and all(c in '0123456789abcdefABCDEF' or c == '_' for c in body):
            if body.startswith('_') or body.endswith('_') or '__' in body:
                return None
            return int(text, 16)

    return None

