def solve(lo: int, hi: int, digit: int) -> int:
    def count_digit_occurrences(n: int, digit: int) -> int:
        if n < 0:
            return 0

        count = 0
        factor = 1

        while n // factor != 0:
            higher = n // (factor * 10)
            current = (n // factor) % 10
            lower = n % factor

            if digit == 0:
                if higher == 0:
                    if n == 0:
                        count += 1
                    else:
                        count += factor + 1
                else:
                    count += (higher - 1) * factor + lower + 1
            else:
                if current < digit:
                    count += higher * factor
                elif current == digit:
                    count += higher * factor + lower + 1
                else:
                    count += (higher + 1) * factor

            factor *= 10

        return count

    return count_digit_occurrences(hi, digit) - count_digit_occurrences(lo - 1, digit)

