    def count_up_to(n: int, d: int) -> int:
        if n < 0:
            return 0
        count = 0
        factor = 1
        while factor <= n:
            lower = n % factor
            cur = (n // factor) % 10
            higher = n // (factor * 10)

            if d == 0:
                if higher == 0:
                    pass  # Don't count leading zeros
                elif cur == d:
                    count += higher * factor + lower + 1
                elif cur > d:
                    count += (higher + 1) * factor
            else:
                if cur < d:
                    count += higher * factor
                elif cur == d:
                    count += higher * factor + lower + 1
                else:
                    count += (higher + 1) * factor

            factor *= 10

