def solve(values: list[int], k: int) -> list[int]:
    n = len(values)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + values[i]

    def can_split(max_sum: int) -> bool:
        parts = 0
        start = 0
        for end in range(1, n + 1):
            if prefix[end] - prefix[start] > max_sum:
                parts += 1
                start = end - 1
                if parts >= k:
                    return False
        return parts < k

    lo, hi = 0, prefix[n]
    while lo < hi:
        mid = (lo + hi) // 2
        if can_split(mid):
            hi = mid
        else:
            lo = mid + 1

    max_sum = lo
    part_ends = []
    start = 0
    for end in range(1, n + 1):
        if prefix[end] - prefix[start] > max_sum:
            part_ends.append(end - 1)
            start = end - 1
            if len(part_ends) == k - 1:
                break

    lengths = []
    prev_end = 0
    for end in part_ends:
        lengths.append(end - prev_end + 1)
        prev_end = end + 1
    lengths.append(n - prev_end)

    return lengths

